import React from "react";
import './Header.css';

function Header() {
    return (
        <>
        <div class="navigation">
            <h2>Portfolio</h2>
            <nav>
                <a href="#">Home</a>
                <a href="#">About</a>
                <a href="#">Project</a>
                <a href="#">Skill</a>
                <a href="#">Contact</a>
                <div class="animation start-home"></div>
            </nav>
        </div>
        </>
    )
}
export default Header;
